51	@@ -0,0 +1,41 @@
52	+using Microsoft.EntityFrameworkCore;
53	+using seed_b_backend.Api.Data;
54	+using seed_b_backend.Api.Dtos;
55	+
56	+namespace seed_b_backend.Api.Application;
57	+
58	+public class SubcategoryPropertyQueryService(AppDbContext db)
59	+{
60	+    public async Task<List<PropertyFilterOptionDto>> GetPropertyFilterOptionsAsync(
61	+        string subcategoryId,
62	+        CancellationToken cancellationToken = default)
63	+    {
64	+        var definitions = await db.PropertyDefinitions
65	+            .AsNoTracking()
66	+            .Where(d => d.SubcategoryId == subcategoryId)
67	+            .OrderBy(d => d.Name)
68	+            .Select(d => new { d.Id, d.Name })
69	+            .ToListAsync(cancellationToken);
70	+
71	+        var definitionIds = definitions.Select(d => d.Id).ToList();
72	+
73	+        var values = await db.ProductProperties
74	+            .AsNoTracking()
75	+            .Where(pp => definitionIds.Contains(pp.PropertyDefinitionId))
76	+            .Select(pp => new { pp.PropertyDefinitionId, pp.Value })
77	+            .Distinct()
78	+            .ToListAsync(cancellationToken);
79	+
80	+        return definitions
81	+            .Select(d => new PropertyFilterOptionDto
82	+            {
83	+                Name = d.Name,
84	+                Values = values
85	+                    .Where(v => v.PropertyDefinitionId == d.Id)
86	+                    .Select(v => v.Value)
87	+                    .OrderBy(v => v)
88	+                    .ToList()
89	+            })
90	+            .ToList();
91	+    }
92	+}
