896	+import { Component, effect, inject, input, output, signal } from '@angular/core';
897	+
898	+import { PropertyFilterOption, SubcategoriesApi } from '../../../core/api/subcategories.api';
899	+
900	+export type PropertyFilterSelection = Record<string, string[]>;
901	+
902	+@Component({
903	+  selector: 'app-property-filter',
904	+  imports: [],
905	+  templateUrl: './property-filter.html',
906	+  styleUrl: './property-filter.scss',
907	+})
908	+export class PropertyFilter {
909	+  private readonly subcategoriesApi = inject(SubcategoriesApi);
910	+
911	+  readonly subcategoryId = input<string | null>(null);
912	+  readonly selection = input<PropertyFilterSelection>({});
913	+  readonly disabled = input(false);
914	+  readonly selectionChange = output<PropertyFilterSelection>();
915	+
916	+  protected readonly options = signal<PropertyFilterOption[]>([]);
917	+  protected readonly loading = signal(false);
918	+  protected readonly error = signal(false);
919	+
920	+  constructor() {
921	+    effect(() => {
922	+      const subcategoryId = this.subcategoryId();
923	+      if (subcategoryId === null) {
924	+        this.options.set([]);
925	+        return;
926	+      }
927	+
928	+      this.loading.set(true);
929	+      this.error.set(false);
930	+      this.subcategoriesApi.getProperties(subcategoryId).subscribe({
931	+        next: (options) => {
932	+          this.options.set(options);
933	+          this.loading.set(false);
934	+        },
935	+        error: () => {
936	+          this.loading.set(false);
937	+          this.error.set(true);
938	+        },
939	+      });
940	+    });
941	+  }
942	+
943	+  protected isChecked(name: string, value: string): boolean {
944	+    return this.selection()[name]?.includes(value) ?? false;
945	+  }
946	+
947	+  protected toggleValue(name: string, value: string, checked: boolean): void {
948	+    const next: PropertyFilterSelection = { ...this.selection() };
949	+    const values = next[name] ?? [];
950	+
951	+    if (checked) {
952	+      next[name] = [...values, value];
953	+    } else {
954	+      const remaining = values.filter((v) => v !== value);
955	+      if (remaining.length > 0) {
956	+        next[name] = remaining;
957	+      } else {
958	+        delete next[name];
959	+      }
960	+    }
961	+
962	+    this.selectionChange.emit(next);
963	+  }
964	+}
