7	public class ProductQueryService(AppDbContext db)
8	{
9	    private const int PageSize = 20;
10	    private const int MaxSearchTermLength = 200;
11	
12	    public async Task<PagedResultDto<ProductListItemDto>> GetProductsAsync(
13	        int page = 1,
14	        string? categoryId = null,
15	        string? subcategoryId = null,
16	        string? sortBy = null,
17	        string? sortDir = null,
18	        string? q = null,
19	        IReadOnlyList<string>? property = null,
20	        CancellationToken cancellationToken = default)
21	    {
22	        if (page < 1)
23	        {
24	            page = 1;
25	        }
26	
27	        var query = db.Products.AsNoTracking().AsQueryable();
28	
29	        if (!string.IsNullOrWhiteSpace(subcategoryId))
30	        {
31	            query = query.Where(p => p.SubcategoryId == subcategoryId);
32	        }
33	        else if (!string.IsNullOrWhiteSpace(categoryId))
34	        {
35	            query = query.Where(p => p.Subcategory.CategoryId == categoryId);
36	        }
37	
38	        if (!string.IsNullOrWhiteSpace(q))
39	        {
40	            var trimmed = q.Trim();
41	            var term = (trimmed.Length > MaxSearchTermLength ? trimmed[..MaxSearchTermLength] : trimmed).ToLowerInvariant();
42	            query = query.Where(p => p.Name.ToLower().Contains(term) || p.Description.ToLower().Contains(term));
43	        }
44	
45	        if (property is { Count: > 0 })
46	        {
47	            var groups = property
48	                .Select(entry =>
49	                {
50	                    var separatorIndex = entry.IndexOf(':');
51	                    if (separatorIndex < 0)
52	                    {
53	                        return (Name: (string?)null, Value: (string?)null);
54	                    }
55	
56	                    var name = entry[..separatorIndex].Trim();
57	                    var value = entry[(separatorIndex + 1)..].Trim();
58	                    return (Name: name, Value: value);
59	                })
60	                .Where(entry => !string.IsNullOrEmpty(entry.Name) && !string.IsNullOrEmpty(entry.Value))
61	                .GroupBy(entry => entry.Name!, entry => entry.Value!);
62	
63	            foreach (var group in groups)
64	            {
65	                var name = group.Key;
66	                var values = group.ToList();
67	                query = query.Where(p => p.ProductProperties.Any(pp => pp.PropertyDefinition.Name == name && values.Contains(pp.Value)));
68	            }
69	        }
70	
71	        var descending = string.Equals(sortDir?.Trim(), "desc", StringComparison.OrdinalIgnoreCase);
72	        query = sortBy?.Trim().ToLowerInvariant() switch
73	        {
74	            "price" => descending
75	                ? query.OrderByDescending(p => p.Offers.Select(o => (decimal?)o.Price).Min()).ThenBy(p => p.Id)
76	                : query.OrderBy(p => p.Offers.Select(o => (decimal?)o.Price).Min()).ThenBy(p => p.Id),
77	            "name" => descending
78	                ? query.OrderByDescending(p => p.Name).ThenBy(p => p.Id)
79	                : query.OrderBy(p => p.Name).ThenBy(p => p.Id),
80	            _ => query.OrderBy(p => p.Id)
81	        };
82	
83	        var totalCount = await query.CountAsync(cancellationToken);
84	        var pageCount = totalCount == 0 ? 0 : (int)Math.Ceiling(totalCount / (double)PageSize);
85	
86	        if (pageCount > 0 && page > pageCount)
87	        {
88	            page = pageCount;
89	        }
90	
91	        var items = await query
92	            .Skip((page - 1) * PageSize)
93	            .Take(PageSize)
94	            .Select(p => new ProductListItemDto
95	            {
96	                Id = p.Id,
97	                Name = p.Name,
98	                LowestPrice = p.Offers.Select(o => (decimal?)o.Price).Min()
99	            })
100	            .ToListAsync(cancellationToken);
101	
102	        return new PagedResultDto<ProductListItemDto>
103	        {
104	            Items = items,
105	            TotalCount = totalCount,
106	            PageCount = pageCount,
107	            Page = page,
108	            PageSize = PageSize
109	        };
110	    }
111	}
